13.query:
fetch spans
| filter lower(gen_ai.system) == "amazon"
| summarize count(), by: {service.name}

40.query:
fetch spans
| filter lower(gen_ai.system) == "amazon"
| summarize { 
      spans=count(),
      trace=takeAny(record(start_time, trace.id)) // pick random trace from aggregation bucket
    }, by: { bin(duration, 10ms) }
| sort `bin(duration, 10ms)` desc
| fields duration=`bin(duration, 10ms)`, trace.id=trace[trace.id], start_time=trace[start_time]
| limit 3

60.query:
timeseries guardrail=avg(gen_ai.bedrock.guardrail.sensitive_info)//, timeframe: "2025-01-08T23:00:00Z/2025-01-09T12:00:00Z"
| fieldsAdd total = arraySum(guardrail)
| append [
  fetch spans
  | filter lower(gen_ai.system) == "amazon"
  | summarize req = count()
  //| fieldsAdd req = arraySum(requests)
]
| summarize {
  c = takeMin(req),
  g = takeMax(total)
}
| fieldsAdd rate = 100*(g/c)

